CREATE EXTENSION IF NOT EXISTS pgcrypto; CREATE TABLE payroll_jobs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employer_account_id UUID NOT NULL,total_items INT NOT NULL,processed_items INT NOT NULL DEFAULT 0,failed_items INT NOT NULL DEFAULT 0,checkpoint_index INT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'queued',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE payroll_items(id BIGSERIAL PRIMARY KEY,job_id UUID NOT NULL REFERENCES payroll_jobs(id),line_index INT NOT NULL,recipient_wallet_id UUID NOT NULL,amount_cents BIGINT NOT NULL CHECK(amount_cents>0),idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',transaction_id UUID,UNIQUE(job_id,line_index)); CREATE INDEX idx_payroll_items_job ON payroll_items(job_id,status);
